Actionscript.script:
// ===== 王财宝具（素材元件）=====
// 素材实况：刀=竖画(刀尖+y) 51×402 / 手枪=横画(枪口+x) 94×60 /
//           长枪=横画(枪口+x) 274×107 / 拳套=手部素材(挂右手的)
// ⇒ 枪比刀多转 90°；尺寸统一用一个倍率，不做同类归一。

this.飞剑.基本款._visible = 0;

var 类型 = _parent.装备类型;                              // ← 必须先取，下面拼后缀要用
if (类型 == undefined || 类型 == "") 类型 = "刀";

var 装扮 = _parent.装扮;
if (装扮 == undefined || 装扮 == "") 装扮 = "刀-中国战刀";   // 兜底，别空手
if (类型 == "拳套") 装扮 = 装扮 + "右手";                   // 拳套 dressup 只是前缀

var 新装扮 = this.飞剑.attachMovie(装扮, "装扮", this.getNextHighestDepth(), {_xscale: 100, _yscale: 100});

if (新装扮 != undefined && 新装扮._height > 0)
{
	var 是枪 = (类型 == "手枪" || 类型 == "长枪");

	// ---- 朝向 ----
	// 飞剑 挂点自带 rot 163.86°，-164 正好抵消（屏幕上≈0°，正）。
	// ⚠ 挂点矩阵 det>0，无镜像；所以屏幕朝向 = 163.86 + _rotation，直接线性相加。
	//   唯一的例外是"取负 _xscale"的枪：自身镜像会把方向翻过去 ⇒ 屏幕朝向 = -(163.86 + _rotation)。
	//   ⇒ 枪和拳套虽然 _rotation 都是 -254，屏幕上一个顺时针 90°、一个逆时针 90°，别串用。
	var 旋转;
	if (是枪)              旋转 = -164 - 90;   // = -254，屏幕顺时针 90°（因 _xscale 取负）
	else if (类型 == "拳套") 旋转 = -164 + 90;   // = -254，屏幕逆时针 90°
	else                   旋转 = -164;        // 刀：屏幕 ≈ 0°

	// ---- 尺寸：唯一总旋钮，所有类型共用（%） ----
	var 基准缩放 = 70;              // 100 → 70：整体缩小 30%

	if (是枪)
	{
		新装扮._xscale = -基准缩放;    // 负值 = 屏幕水平镜像
	}
	else if (类型 == "拳套")
	{
		基准缩放 = 105;              // 150 → 105：同步缩 30%（拳套素材偏小，仍保持 1.5 倍）
		新装扮._xscale = 基准缩放;
	}
	else
	{
		新装扮._xscale = 基准缩放;
	}
	新装扮._yscale = 基准缩放;
	新装扮._rotation = 旋转;

	// ---- 挂点位置（飞剑 局部坐标）----
	// 这个坐标系被挂点矩阵转了 163.86°，所以 局部 +y ≈ 屏幕"左上"，即剑尖方向(前)。
	// 局部 +y = 25 换算到屏幕 ≈ 向左 4px、向上 14px（父级还有 0.6 倍缩放）。
	if (类型 == "拳套")
	{
		新装扮._x = 0;
		新装扮._y = 5;
	}
	else if (是枪)
	{
		新装扮._x = -12;
		新装扮._y = 11;        // 枪单独往前
	}
	else
	{
		新装扮._x = -12;
		新装扮._y = 91;         // 刀不动
	}
}
